import java.util.*;

class Solution {
  public List<String> restoreIpAddresses(String s) {
    List<String> ans = new ArrayList<>();
    build(s, 0, new ArrayList<>(), ans);
    return ans;
  }

  private void build(String s, int start, List<String> parts, List<String> ans) {
    if (parts.size() == 4) {
      if (start == s.length()) ans.add(String.join(".", parts));
      return;
    }
    for (int len = 1; len <= 3 && start + len <= s.length(); len++) {
      String part = s.substring(start, start + len);
      if ((part.length() > 1 && part.charAt(0) == '0') || Integer.parseInt(part) > 255) continue;
      parts.add(part);
      build(s, start + len, parts, ans);
      parts.remove(parts.size() - 1);
    }
  }
}
